function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 300) return 'arr needs 1 to 300 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 100000000)) return 'Each value is an integer from 1 to 10^8.';
