function countTriplets(arr) {
  const count = new Map([[0, 1]]);
  const positionSum = new Map([[0, 0]]);
  let prefix = 0;
  let triplets = 0;
  for (let k = 0; k < arr.length; k++) {
    prefix ^= arr[k];
    const seen = count.get(prefix) ?? 0;
    const total = positionSum.get(prefix) ?? 0;
    triplets += seen * k - total;
    count.set(prefix, seen + 1);
    positionSum.set(prefix, total + k + 1);
  }
  return triplets;
}

