function generate(rand, size) {
  const top = [3, 8, 100000000][Math.floor(rand() * 3)];
  const n = size === 'large' ? 300 : 1 + Math.floor(rand() * 10);
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
